"""Isolated browser-only practice; no order creation or network mutations."""
import json
from html import escape

SCENARIOS=[
 {'id':'normal','title':'1. 정상 주문과 배송','prompt':'모의 결제 완료 후 문구·제작 파일 검수까지 마쳤습니다. 실제 설치 출발을 확인했습니다. 다음 처리는?','answers':['배송 중으로 변경','결제 완료를 수동 입력','배송 완료부터 변경'],'correct':0,'result':'정답: 주문 확인 → 배송 중 → 실제 설치 후 배송 완료 순서입니다. 실제 주문은 변경되지 않았습니다.','stage':'배송 중'},
 {'id':'timeout','title':'2. 결제 요청 결과 불명','prompt':'결제 요청이 타임아웃됐지만 판매자 거래 내역은 아직 확인하지 못했습니다.','answers':['새 결제를 즉시 요청','주문번호·원금액·결제번호로 기존 거래 대조','배송부터 시작'],'correct':1,'result':'정답: 결과 불명은 원거래를 먼저 대조합니다. 확인된 통보를 기준으로 처리하며 중복 결제를 요청하지 않습니다.','stage':'결제 확인 필요'},
 {'id':'partial','title':'3. 부분취소 주문','prompt':'원결제 110,000원 중 20,000원이 취소됐습니다. 남은 금액과 제작 재개 여부를 확인해야 합니다.','answers':['원결제를 90,000원으로 덮어쓰기','부분취소를 무시하고 배송','원금액·취소 누계·잔액 90,000원 대조 후 재개 판단'],'correct':2,'result':'정답: 원결제금액은 보존합니다. 취소 누계와 잔액을 대조하고 제작·배송 재개를 판단합니다.','stage':'부분취소 검토'},
 {'id':'late','title':'4. 취소 뒤 늦은 승인 통보','prompt':'취소 처리된 주문에 결제 완료 통보가 늦게 도착했습니다.','answers':['취소 내역 유지 후 판매자 거래 대조','자동 제작 재개','새 주문번호로 재결제'],'correct':0,'result':'정답: 늦은 승인 통보만으로 취소 주문의 제작·배송을 재개하지 않습니다. 거래 내역을 대조합니다.','stage':'취소 유지'},
 {'id':'amend','title':'5. 문구 정정과 인수인계','prompt':'검수 후 문구 정정이 승인됐습니다. 이전 제작 파일과 인수인계 체크가 있습니다.','answers':['이전 파일을 그대로 제작','새 문구로 파일 재생성·검수 후 인수인계 재확인','고객용 요약에 직원 메모 첨부'],'correct':1,'result':'정답: 원주문 금액은 유지하고 승인된 문구로 다시 검수합니다. 인수인계도 최신 주문을 기준으로 확인합니다.','stage':'재검수 필요'}]


def entry(path):return '<section><h2>직원 교육</h2><p>가상 주문 다섯 사례로 결제 대조·배송·정정 처리를 연습합니다.</p><a href="'+escape(path+'/training')+'">직원 교육 시작</a></section>'


def page(path):
    data=json.dumps(SCENARIOS,ensure_ascii=False).replace('<','\\u003c')
    return '''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>벨라비타 직원 교육</title><style>body{font:16px/1.7 system-ui;background:#f5f5ef;color:#243329;margin:0}main{max-width:850px;margin:auto;padding:20px}section{background:white;border:1px solid #dce3d8;padding:20px;border-radius:12px;margin:18px 0}button{font:inherit;padding:12px;border-radius:7px;border:1px solid #aab5aa;margin:6px 4px 6px 0;cursor:pointer}label{display:block;padding:10px}p{overflow-wrap:anywhere}.practice-sample{border:3px solid #b7a582;padding:20px;max-width:280px;text-align:center;margin:12px auto;white-space:pre-line}#training-result{padding:14px;background:#edf3e9}button[aria-pressed=true]{background:#284d39;color:white}</style><main><h1>직원 교육 · 모의 주문</h1><p><a href="'''+escape(path)+'''">관리자로 돌아가기</a> · <a href="'''+escape(path+'/manual')+'''">관리 매뉴얼</a></p><p>고정된 가상 데이터로 브라우저 안에서만 연습합니다. 실제 주문·결제·배송·알림·영수증 기록을 만들거나 변경하지 않습니다. 새로고침하면 교육 진행이 초기화됩니다.</p><nav id="training-cases" aria-label="교육 사례"></nav><p id="training-score" role="status">완료 0/5</p><section><h2 id="case-title"></h2><p id="case-prompt"></p><div class="practice-sample">교육용 문구 예시<br>새 출발을 축하합니다<br>보내는 분: 모의 고객</div><p>모의 주문번호: 교육-001 · 원결제 110,000원</p><p id="training-stage">모의 상태: 주문 확인</p><div id="training-answers"></div><button id="training-run" type="button">선택 결과 확인</button><p id="training-result" role="status">사례를 선택하고 처리 방법을 골라 주세요.</p></section><button id="training-reset" type="button">교육 처음부터</button></main><script>
const cases='''+data+''';let active=0;const completed=new Set();const nav=document.getElementById('training-cases');
function render(){const item=cases[active];document.getElementById('case-title').textContent=item.title;document.getElementById('case-prompt').textContent=item.prompt;const answers=document.getElementById('training-answers');answers.replaceChildren();item.answers.forEach((text,index)=>{const label=document.createElement('label');const input=document.createElement('input');input.type='radio';input.name='practice-answer';input.value=index;label.append(input,document.createTextNode(text));answers.append(label);});document.getElementById('training-result').textContent='처리 방법을 선택하세요.';document.getElementById('training-stage').textContent='모의 상태: 연습 대기';for(const [index,button] of Array.from(nav.children).entries())button.setAttribute('aria-pressed',String(index===active));}
cases.forEach((item,index)=>{const button=document.createElement('button');button.type='button';button.textContent=item.title;button.addEventListener('click',()=>{active=index;render();});nav.append(button);});
document.getElementById('training-run').addEventListener('click',()=>{const selected=document.querySelector('[name=practice-answer]:checked');const result=document.getElementById('training-result');if(!selected){result.textContent='처리 방법을 먼저 선택하세요.';return;}const item=cases[active];if(Number(selected.value)!==item.correct){result.textContent='다시 확인하세요. 실제 처리 전에는 결제·검수·취소 상태와 근거를 먼저 대조합니다.';return;}completed.add(item.id);result.textContent=item.result;document.getElementById('training-stage').textContent='모의 상태: '+item.stage;document.getElementById('training-score').textContent='완료 '+completed.size+'/5';});
document.getElementById('training-reset').addEventListener('click',()=>{completed.clear();active=0;document.getElementById('training-score').textContent='완료 0/5';render();});render();
</script></html>'''
